fn contains_z(s: &str) -> bool {
    // Requires: s is a valid string slice
    // Ensures: returns true if 'z' or 'Z' is present in the string, false otherwise
    // Decreases: the length of the string as we iterate through its characters
    let mut found_z = false;
    let len = s.len();
    
    // Invariant: at any point in the iteration, found_z is true if 'z' or 'Z' has been found in the processed part of the string
    // Loop invariant: 0 <= i <= len && found_z == (s[..i].contains('z') || s[..i].contains('Z'))
    for (i, c) in s.chars().enumerate() {
        // Assert: i is within bounds of the string
        assert!(i < len);
        
        if c == 'z' || c == 'Z' {
            found_z = true;
        }
    }
    
    found_z
}

