    // Example usage
    let test_str1 = "Hello, World!";
    let test_str2 = "Amazing Zebra";
    let test_str3 = "No Z here";

    println!("{}", contains_z(test_str1)); // false
    println!("{}", contains_z(test_str2)); // true
    println!("{}", contains_z(test_str3)); // true
